<script setup lang="ts">
import {ref,computed} from 'vue'
const people=[{id:'ana',name:'Ana Rivera',initials:'AR'},{id:'sam',name:'Sam Lee',initials:'SL'},{id:'jo',name:'Jo Chen',initials:'JC'},{id:'mia',name:'Mia Patel',initials:'MP'},{id:'eli',name:'Eli Cruz',initials:'EC'}]
const size=ref('md'),mode=ref('initials'),status=ref('Available'),limit=ref(3),failed=ref(false)
const shown=computed(()=>people.slice(0,limit.value)),remaining=computed(()=>people.length-shown.value.length)
const portrait='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="96" height="96" viewBox="0 0 96 96"><rect width="96" height="96" fill="#5360b9"/><circle cx="48" cy="35" r="18" fill="#f4d6b3"/><path d="M14 96V82c0-34 68-34 68 0v14" fill="#d8e0ff"/></svg>')
function changeMode(){failed.value=mode.value==='broken'}
function reset(){size.value='md';mode.value='initials';status.value='Available';limit.value=3;failed.value=false}
</script>
<template><section class="avatar-usage" aria-label="Avatar usage demonstration"><p>Fictitious sample identities and an original geometric portrait. Status is chosen locally, not live presence.</p><div class="options"><label>Avatar size<select v-model="size"><option>sm</option><option>md</option><option>lg</option></select></label><label>Avatar content<select v-model="mode" @change="changeMode"><option value="initials">Initials</option><option value="image">Local image</option><option value="broken">Simulate image failure</option></select></label><label>Sample status<select v-model="status"><option>Available</option><option>Busy</option><option>Offline</option></select></label><label>Visible group members<select v-model.number="limit"><option :value="2">2</option><option :value="3">3</option><option :value="5">5</option></select></label><button type="button" @click="reset">Reset avatars</button></div><h3>Single identity</h3><div class="identity"><span class="avatar" :class="size" aria-hidden="true"><img v-if="mode==='image'&&!failed" :src="portrait" alt="" @error="failed=true"><span v-else>AR</span><i class="dot" :class="status.toLowerCase()"></i></span><div><strong>Ana Rivera</strong><p class="status-text">{{status}} · {{failed?'Initials fallback':mode==='image'?'Local image':'Initials'}}</p></div></div><h3>Stacked group</h3><ul class="group" aria-label="Sample project members"><li v-for="person in shown" :key="person.id"><span class="avatar" :class="size" role="img" :aria-label="person.name">{{person.initials}}</span></li><li v-if="remaining"><span class="avatar overflow" :class="size" role="img" :aria-label="`${remaining} more sample members`">+{{remaining}}</span></li></ul><p class="members">All sample members: {{people.map(x=>x.name).join(', ')}}.</p><p v-if="failed" role="status">Simulated image failure: initials remain available. No broken URL was requested.</p></section></template>
<style scoped>
.avatar-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}.options{display:flex;flex-wrap:wrap;gap:12px;align-items:end}label{display:flex;flex-direction:column;gap:8px}button,select{min-height:44px;padding:8px 12px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.identity{display:flex;gap:20px;align-items:center;margin:20px 0}.status-text{margin:4px 0}.avatar{position:relative;display:inline-flex;flex-shrink:0;align-items:center;justify-content:center;width:48px;height:48px;border-radius:50%;background:var(--vp-c-brand-soft);color:var(--vp-c-text-1);border:2px solid var(--vp-c-bg);font-size:15px;font-weight:650;transition:width 160ms ease-out,height 160ms ease-out}.avatar.sm{width:32px;height:32px;font-size:11px}.avatar.lg{width:64px;height:64px;font-size:18px}.avatar img{width:100%;height:100%;border-radius:50%;object-fit:cover}.dot{position:absolute;bottom:0;right:0;width:11px;height:11px;border-radius:50%;border:2px solid var(--vp-c-bg)}.available{background:#49b887}.busy{background:#db9751}.offline{background:#8b90a2}.group{display:flex;flex-wrap:wrap;list-style:none!important;padding:4px!important;margin:20px 0!important}.group li{padding:0;margin:0 0 0 -8px!important}.group li:first-child{margin-left:0!important}.overflow{background:var(--vp-c-bg-soft)}.members{overflow-wrap:anywhere}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:2px}@media(prefers-reduced-motion:reduce){.avatar{transition:none}}
</style>
